<?php
require_once __DIR__ . '/../conexao.php'; require_once __DIR__ . '/resposta.php'; exigirMetodo('POST');
$d=lerDadosRequisicao(); $email=strtolower(trim((string)($d['email']??''))); $token=(string)($d['token_redefinicao']??''); $senha=(string)($d['senha']??''); $confirmacao=(string)($d['confirmacao_senha']??'');
if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($token)!==64) responderErro(422,'A recuperacao nao e valida. Solicite um novo codigo.'); if(strlen($senha)<8) responderErro(422,'A senha deve ter pelo menos 8 caracteres.'); if($senha!==$confirmacao) responderErro(422,'A confirmacao da senha nao confere.');
$hash=hash('sha256',$token); $s=$conexao->prepare('SELECT r.id_recuperacao,r.id_usuario FROM recuperacoes_senha r INNER JOIN usuarios u ON u.id_usuario=r.id_usuario WHERE u.email=? AND r.token_redefinicao_hash=? AND r.verificado_em IS NOT NULL AND r.usado_em IS NULL AND r.expira_em>=NOW() LIMIT 1'); $s->bind_param('ss',$email,$hash); $s->execute(); $r=$s->get_result()->fetch_assoc(); $s->close(); if(!$r) responderErro(400,'A recuperacao expirou ou ja foi utilizada.');
$senhaHash=password_hash($senha,PASSWORD_DEFAULT); $conexao->begin_transaction(); try {$idU=(int)$r['id_usuario']; $s=$conexao->prepare('UPDATE usuarios SET senha_hash=? WHERE id_usuario=?');$s->bind_param('si',$senhaHash,$idU);$s->execute();$s->close();$idR=(int)$r['id_recuperacao'];$s=$conexao->prepare('UPDATE recuperacoes_senha SET usado_em=NOW() WHERE id_recuperacao=?');$s->bind_param('i',$idR);$s->execute();$s->close();$conexao->commit();}catch(Throwable $e){$conexao->rollback();responderErro(500,'Nao foi possivel redefinir a senha.');}
responderJson(200,['mensagem'=>'Senha redefinida com sucesso. Entre com sua nova senha.']);
